  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.amount) return;
    setIsSubmitting(true);

    const expense: Expense = {
      id: editingExpense?.id || `exp-${Date.now()}`,
      title: formData.title!,
      amount: Number(formData.amount),
      currency: formData.currency as Currency,
      category: formData.category as ExpenseCategory,
      date: formData.date!,
      paidTo: formData.paidTo!,
      description: formData.description,
      files: formData.files,
      status: formData.status as 'paid' | 'pending',
      createdAt: editingExpense?.createdAt || new Date().toISOString(),
      createdBy: editingExpense?.createdBy || currentUser.fullName
    };

    if (editingExpense) {
      await updateExpense(expense.id, expense, currentUser.fullName);
    } else {
      await saveExpense(expense, currentUser.fullName);
    }

    setIsSubmitting(false);
    setShowAddModal(false);
    setEditingExpense(null);
    setFormData({ title: '', amount: 0, currency: 'IRR', category: 'operational', date: new Date().toISOString().split('T')[0], paidTo: '', description: '', status: 'paid', files: [] });
  };

  const handleDelete = async (id: string) => {
    if (window.confirm(t.deleteConfirm)) {
      await deleteExpense(id, currentUser.fullName);
    }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
    setFormData(prev => ({ ...prev, files: [...(prev.files || []), newFile] }));

    uploadFileWithProgress(
      file,
      (progress) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, progress } : f) }));
      },
      (url) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f) }));
      },
      (err) => {
        setFormData(prev => ({ ...prev, files: prev.files?.map(f => f.name === file.name ? { ...f, status: 'error' } : f) }));
      }
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-2xl border border-gray-100 shadow-sm gap-4">
        <div>
          <h2 className="text-xl font-bold text-gray-800 flex items-center gap-2">
            <div className="bg-rose-100 text-rose-600 p-2 rounded-lg"><IconWallet className="w-6 h-6" /></div>
            {t.header}
          </h2>
          <p className="text-sm text-gray-500 mt-1">{t.sub}</p>
        </div>
        <button onClick={() => { setEditingExpense(null); setFormData({ title: '', amount: 0, currency: 'IRR', category: 'operational', date: new Date().toISOString().split('T')[0], paidTo: '', description: '', status: 'paid', files: [] }); setShowAddModal(true); }} className="bg-rose-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-rose-700 flex items-center gap-2 shadow-lg shadow-rose-200 transition-all">
          <IconPlus className="w-5 h-5" /> {t.add}
        </button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
          <div className="text-gray-500 text-xs font-bold mb-1">{t.stats.total}</div>
          <div className="text-xl font-black text-gray-800">{stats.total.toLocaleString()} <span className="text-xs text-gray-400 font-normal">IRR</span></div>
        </div>
        <div className="bg-blue-50 p-5 rounded-2xl border border-blue-100 shadow-sm">
          <div className="text-blue-700 text-xs font-bold mb-1">{t.stats.operational}</div>
          <div className="text-xl font-black text-blue-600">{stats.operational.toLocaleString()}</div>
        </div>
        <div className="bg-purple-50 p-5 rounded-2xl border border-purple-100 shadow-sm">
          <div className="text-purple-700 text-xs font-bold mb-1">{t.stats.non_operational}</div>
          <div className="text-xl font-black text-purple-600">{stats.non_operational.toLocaleString()}</div>
        </div>
        <div className="bg-amber-50 p-5 rounded-2xl border border-amber-100 shadow-sm">
          <div className="text-amber-700 text-xs font-bold mb-1">{t.stats.pending}</div>
          <div className="text-xl font-black text-amber-600">{stats.pending.toLocaleString()}</div>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-grow w-full">
          <IconSearch className="absolute right-3 top-3 w-4 h-4 text-gray-400" />
          <input className="w-full pl-4 pr-10 py-2.5 bg-gray-50 border-none rounded-xl text-sm outline-none focus:bg-white focus:ring-2 focus:ring-rose-100" placeholder="جستجو در شرح هزینه یا گیرنده..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <select className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" value={categoryFilter} onChange={e => setCategoryFilter(e.target.value as any)}>
            <option value="all">{t.categories.all}</option>
            {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
          </select>
          <input type="month" className="px-4 py-2.5 bg-gray-50 rounded-xl text-sm border-none font-bold text-gray-600 outline-none" value={dateFilter} onChange={e => setDateFilter(e.target.value)} />
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right text-sm">
            <thead className="bg-gray-50 text-gray-500 font-bold uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">{t.table.title}</th>
                <th className="px-6 py-4">{t.table.amount}</th>
                <th className="px-6 py-4">{t.table.cat}</th>
                <th className="px-6 py-4">{t.table.to}</th>
                <th className="px-6 py-4">{t.table.date}</th>
                <th className="px-6 py-4 text-center">{t.table.status}</th>
                <th className="px-6 py-4 text-center">عملیات</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredExpenses.map(ex => (
                <tr key={ex.id} className="hover:bg-gray-50 transition-colors group">
                  <td className="px-6 py-4 font-bold text-gray-800">{ex.title}</td>
                  <td className="px-6 py-4 font-black text-rose-600">{ex.amount.toLocaleString()} <span className="text-[10px] font-normal text-gray-400">{ex.currency}</span></td>
                  <td className="px-6 py-4"><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{t.categories[ex.category as keyof typeof t.categories]}</span></td>
                  <td className="px-6 py-4 text-gray-600">{ex.paidTo}</td>
                  <td className="px-6 py-4 text-gray-400 dir-ltr">{ex.date}</td>
                  <td className="px-6 py-4 text-center"><span className={`px-2 py-1 rounded text-[10px] font-bold ${ex.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{ex.status === 'paid' ? t.paid : t.pending}</span></td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => { setEditingExpense(ex); setFormData(ex); setShowAddModal(true); }} className="p-1.5 text-blue-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg"><IconEdit className="w-4 h-4" /></button>
                      {isMaster && <button onClick={() => handleDelete(ex.id)} className="p-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg"><IconTrash className="w-4 h-4" /></button>}
                    </div>
                  </td>
                </tr>
              ))}
              {filteredExpenses.length === 0 && <tr><td colSpan={7} className="text-center py-12 text-gray-400">{t.empty}</td></tr>}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-gray-900/60 backdrop-blur-md p-4 animate-fade-in" onClick={() => setShowAddModal(false)}>
          <div className="bg-white rounded-[2rem] w-full max-w-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
            <div className="p-6 border-b border-gray-100 bg-rose-50 flex justify-between items-center">
              <h3 className="font-black text-xl text-rose-900 flex items-center gap-2"><IconWallet className="w-5 h-5" />{editingExpense ? t.edit : t.add}</h3>
              <button onClick={() => setShowAddModal(false)} className="p-2 hover:bg-rose-100 rounded-full">✕</button>
            </div>
            <form onSubmit={handleSave} className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.title}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-bold" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="مثلاً: هزینه خرید تجهیزات..." />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.amount}</label>
                  <div className="flex gap-2">
                    <input type="number" required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 transition-all font-black text-rose-600" value={formData.amount || ''} onChange={e => setFormData({...formData, amount: parseFloat(e.target.value)})} placeholder="0" />
                    <select className="px-2 border rounded-xl bg-gray-50 outline-none" value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as any})}><option value="IRR">ریال</option><option value="USD">دلار</option><option value="OMR">عمان</option></select>
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.category}</label>
                  <select className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 bg-white" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as any})}>
                    {Object.keys(t.categories).filter(k => k !== 'all').map(cat => <option key={cat} value={cat}>{t.categories[cat as keyof typeof t.categories]}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.date}</label>
                  <input type="date" required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.paidTo}</label>
                  <input required className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500 font-bold" value={formData.paidTo} onChange={e => setFormData({...formData, paidTo: e.target.value})} placeholder="شخص یا شرکت" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-1 uppercase tracking-widest">{t.desc}</label>
                  <textarea rows={2} className="w-full px-4 py-3 rounded-xl border border-gray-200 outline-none focus:border-rose-500" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.status}</label>
                  <div className="flex gap-4">
                    <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border-2 cursor-pointer transition-all ${formData.status === 'paid' ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-100 bg-gray-50'}`} onClick={() => setFormData({...formData, status: 'paid'})}>
                      <IconCheck className="w-4 h-4" /> <span className="font-bold">{t.paid}</span>
                    </label>
                    <label className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-xl border-2 cursor-pointer transition-all ${formData.status === 'pending' ? 'border-amber-500 bg-amber-50 text-amber-700' : 'border-gray-100 bg-gray-50'}`} onClick={() => setFormData({...formData, status: 'pending'})}>
                      <IconClock className="w-4 h-4" /> <span className="font-bold">{t.pending}</span>
                    </label>
                  </div>
                </div>
                <div className="md:col-span-2">
                   <label className="block text-xs font-bold text-gray-400 mb-2 uppercase tracking-widest">{t.receipt}</label>
                   <div onClick={() => fileInputRef.current?.click()} className="border-2 border-dashed border-gray-200 rounded-xl p-6 text-center cursor-pointer hover:border-rose-400 hover:bg-rose-50/30 transition-all">
                      <IconFileText className="w-8 h-8 text-gray-300 mx-auto mb-2" />
                      <p className="text-xs text-gray-500 font-bold">برای آپلود کلیک کنید (فاکتور، فیش واریز و ...)</p>
                      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} />
                   </div>
                   <div className="flex flex-wrap gap-2 mt-3">
                     {formData.files?.map((f, i) => (
                       <div key={i} className="flex items-center gap-2 bg-gray-50 border border-gray-100 p-2 rounded-lg text-xs">
                         <IconFileText className="w-3 h-3 text-rose-500" />
                         <span className="max-w-[100px] truncate">{f.name}</span>
                         {f.status === 'uploading' && <span className="text-[10px] text-blue-500">{Math.round(f.progress || 0)}%</span>}
                         <button type="button" onClick={() => setFormData(p => ({...p, files: p.files?.filter((_, idx) => idx !== i)}))} className="text-red-400">✕</button>
                       </div>
                     ))}
                   </div>
                </div>
              </div>
            </form>
            <div className="p-6 border-t border-gray-100 flex gap-3 bg-white">
              <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3 text-gray-500 font-bold hover:bg-gray-50 rounded-2xl transition-all">{t.cancel}</button>
              <button onClick={handleSave} disabled={isSubmitting} className="flex-1 py-3 bg-rose-600 text-white font-bold rounded-2xl shadow-xl shadow-rose-200 hover:bg-rose-700 transition-all flex justify-center items-center gap-2">
                {isSubmitting ? '...' : <><IconCheck className="w-5 h-5" /> {t.save}</>}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

